for (int i = 0; i < sortedPoints.size(); ++i) {
    for (int j = i + 1; j < sortedPoints.size(); ++j) {
        for (int k = j + 1; k < sortedPoints.size(); ++k) {
            const Point2d& p1 = sortedPoints[i];
            const Point2d& p2 = sortedPoints[j];
            const Point2d& p3 = sortedPoints[k];

            double det = (p2.x - p1.x) * (p3.y - p1.y) - (p2.y - p1.y) * (p3.x - p1.x);
            if (std::abs(det) < 1e-10) continue;

            double cx = ((p2.x * p2.x + p2.y * p2.y) * (p3.y - p1.y) + (p3.x * p3.x + p3.y * p3.y) * (p1.y - p2.y) + (p1.x * p1.x + p1.y * p1.y) * (p2.y - p3.y)) / (2 * det);
            double cy = ((p2.x * p2.x + p2.y * p2.y) * (p3.x - p1.x) + (p3.x * p3.x + p3.y * p3.y) * (p1.x - p2.x) + (p1.x * p1.x + p1.y * p1.y) * (p2.x - p3.x)) / (2 * det);
            double r2 = (cx - p1.x) * (cx - p1.x) + (cy - p1.y) * (cy - p1.y);

            if (r2 > alpha * alpha) continue;

            bool empty = true;
            for (int l = 0; l < sortedPoints.size(); ++l) {
                if (l == i || l == j || l == k) continue;
                const Point2d& p = sortedPoints[l];
                double d2 = (cx - p.x) * (cx - p.x) + (cy - p.y) * (cy - p.y);
                if (d2 < r2 + 1e-10) {
                    empty = false;
                    break;
                }
            }

            if (empty) {
                tri.push_back({i, j, k});
            }
        }
    }
}

std::set<std::pair<int, int>> alphaEdgeSet;
for (const auto& t : tri) {
    for (int i = 0; i < 3; ++i) {
        int a = t[i], b = t[(i + 1) % 3];
        if (a > b) std::swap(a, b);
        alphaEdgeSet.insert({a, b});
    }
}

std::vector<std::vector<int>> adj(points.size());
for (const auto& e : alphaEdgeSet) {
    adj[e.first].push_back(e.second);
    adj[e.second].push_back(e.first);
}

std::vector<bool> visited(points.size(), false);
int components = 0;
for (int i = 0; i < points.size(); ++i) {
    if (!visited[i]) {
        components++;
        std::queue<int> q;
        q.push(i);
        visited[i] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

return components;

